insert into public.profiles (id, username, display_name, avatar_url, bio, about, links, is_public, created_at) values
  ('35df0732-07a1-5c54-acdf-ddde494f280e', 'vince.rehms', 'Vince Rehms', null, 'Travel photographer in Bali. Everything here I own, use and would buy again.', 'I shoot travel and food around Indonesia and I get asked the same question every week: what''s in the bag? This is the answer, kept up to date. If I stopped using something, it comes off the list.
insert into public.lists (id, owner_id, slug, name, intro, cover_url, is_public, numbered, position, created_at, updated_at) values
  ('a7b02bd5-b543-5aa0-a202-5447bc14907c', '35df0732-07a1-5c54-acdf-ddde494f280e', 'camera-bag-essentials', 'Camera bag essentials', 'What''s in the bag on a shoot day. Nothing sponsored; I bought all of it, and I''ve replaced the things that broke.', '/demo/covers/plum.svg', true, true, 0, '2026-08-01T03:00:00+00:00', '2026-11-04T03:00:00+00:00'),
  ('e45f1901-56bc-5a09-a677-c8b617765d85', '35df0732-07a1-5c54-acdf-ddde494f280e', 'desk-setup', 'Desk setup', 'Where the editing happens. I keep it to things that earn the space.', '/demo/covers/sage.svg', true, false, 1, '2026-08-01T03:00:00+00:00', '2026-10-21T03:00:00+00:00'),
  ('c2c4df9e-302c-5140-a58c-b8ae7858543f', '35df0732-07a1-5c54-acdf-ddde494f280e', 'bali-travel-kit', 'Bali travel kit', 'For scooter days and boat days. Everything here has been rained on.', '/demo/covers/slate.svg', true, false, 2, '2026-08-01T03:00:00+00:00', '2026-10-02T03:00:00+00:00'),
  ('828e5706-c8bc-5594-a966-bface81d1686', '35df0732-07a1-5c54-acdf-ddde494f280e', 'coffee-at-home', 'Coffee at home', 'One good cup before the light gets harsh.', '/demo/covers/umber.svg', true, false, 3, '2026-08-01T03:00:00+00:00', '2026-09-12T03:00:00+00:00'),
  ('87281383-040c-5b1e-a422-a4f9b15f6df0', '3d77bff1-6a15-55f5-a597-4dcb14aec420', 'trail-runs', 'Trail runs', 'What I carry for anything over an hour in the hills.', '/demo/covers/sage.svg', true, true, 0, '2026-08-01T03:00:00+00:00', '2026-11-01T03:00:00+00:00'),
  ('123e753a-0d5c-5190-a469-d3553f47ff26', '3d77bff1-6a15-55f5-a597-4dcb14aec420', 'studio-shelf', 'Studio shelf', 'The few tools I''d buy again tomorrow.', '/demo/covers/rose.svg', true, false, 1, '2026-08-01T03:00:00+00:00', '2026-10-11T03:00:00+00:00'),
  ('edf4689d-a38b-5103-aebd-8d4ca5e296e6', '175c4eaa-e43f-57b2-ad95-7b0ba4fc53fe', 'scooter-kit', 'Scooter kit', 'Everything under the seat, in the order I''d replace it.', '/demo/covers/slate.svg', true, true, 0, '2026-08-01T03:00:00+00:00', '2026-10-28T03:00:00+00:00'),
  ('326e0162-69b5-56bb-a975-3f51071d6a56', '175c4eaa-e43f-57b2-ad95-7b0ba4fc53fe', 'roadside-coffee', 'Roadside coffee', 'For the long way round.', '/demo/covers/umber.svg', true, false, 1, '2026-08-01T03:00:00+00:00', '2026-09-18T03:00:00+00:00')
