insert into public.reviews (product_id, body_text, tidied, published_at, updated_at) values
  ('0d1aed05-cbae-5284-a116-a55334331097', 'I''ve carried this through four countries and it still looks new. The strap is the reason I bought it: one pull and the bag swings to the front, and the magnetic latch has never once opened on its own in a crowd. It takes a mirrorless body with a 35mm, a spare battery and a phone, and nothing more, which is the point.', false, '2026-08-10T03:00:00+00:00', '2026-08-10T03:00:00+00:00'),
  ('16b450ba-7ddf-5115-ab37-e54d87235bb4', 'Small enough that I actually bring it. I shoot it with one 35mm lens most days, and the battery gets me through a full day of walking around. The flip screen is the part I didn''t know I needed.', false, '2026-08-12T03:00:00+00:00', '2026-08-12T03:00:00+00:00'),
  ('e2a3d98b-5847-589a-add1-a151cb7df8c2', 'Two batteries and a card wallet in one zip. Dull, but it ended the ritual of emptying the whole bag on a café table to find a card.', false, '2026-09-02T03:00:00+00:00', '2026-09-02T03:00:00+00:00'),
  ('bb9a46fe-0d8c-519f-afec-d22055806526', 'Every shoot gets a page: the brief, the shot list, the invoice. I tried three other tools and came back each time, mostly because clients can open a page without making an account.', false, '2026-08-20T03:00:00+00:00', '2026-08-20T03:00:00+00:00'),
  ('ad40b05d-0794-579b-a48c-2bc4fc091af6', 'It lights the desk and not the screen, so I can edit at night without a lamp reflecting in the photo I''m grading. I forget it''s there, which is the best thing I can say about a lamp.', false, '2026-09-15T03:00:00+00:00', '2026-09-15T03:00:00+00:00'),
  ('70c1569d-e378-5ae9-ae7d-cddf361a101a', 'The camera goes in here the moment a boat is involved. Roll it three times and it floats; I tested that by accident off Nusa Penida.', false, '2026-09-20T03:00:00+00:00', '2026-09-20T03:00:00+00:00'),
  ('22c92968-e99b-5fd0-a2e6-19efd0e617b3', 'Doesn''t run into my eyes when I sweat, which rules out most of the others I tried. One tube lasts me about a month of shooting outside.', false, '2026-09-22T03:00:00+00:00', '2026-09-22T03:00:00+00:00'),
  ('86badf18-ff3b-55b5-ad3f-b7bc101872a2', 'Forty seconds of grinding and the kitchen smells right. I bought it for travel and it never left the house.', false, '2026-09-10T03:00:00+00:00', '2026-09-10T03:00:00+00:00'),
  ('03d769b9-8c89-5438-a54a-5837348bc5da', 'It doesn''t bounce, even full. I''ve washed it more times than I can count and the mesh hasn''t stretched.', false, '2026-08-18T03:00:00+00:00', '2026-08-18T03:00:00+00:00'),
  ('d983f032-7601-545c-a709-869eb96f07de', 'Shrinks as you drink, so nothing sloshes. Buy two; you will lose a cap.', false, '2026-08-18T03:00:00+00:00', '2026-08-18T03:00:00+00:00'),
  ('4b88cd29-548c-541e-a515-7282be8df7f8', 'For the 5am starts. Bright enough to see roots, light enough that I forget I''m wearing it by the second kilometre.', false, '2026-10-05T03:00:00+00:00', '2026-10-05T03:00:00+00:00'),
  ('8b6ffa42-83ed-533a-a661-c7848450eca3', 'Three loops, and I use one of them for nearly everything. They hold an edge far longer than the set I learned on.', false, '2026-09-08T03:00:00+00:00', '2026-09-08T03:00:00+00:00'),
  ('b5a4b688-52fe-5240-a97f-8aeb0b69c3ab', 'Covers both knees at the wheel. It took me two years of ruined trousers to buy one.', false, '2026-09-08T03:00:00+00:00', '2026-09-08T03:00:00+00:00'),
  ('d1e54113-f57f-5668-a9e8-121fb4ed620d', 'Long enough to cover my knees while riding, and the hood fits under a helmet. It lives under the seat from November to March.', false, '2026-08-25T03:00:00+00:00', '2026-08-25T03:00:00+00:00'),
  ('5e00bd05-574e-5c18-ac3a-da5623ab7ee8', 'Hasn''t dropped the phone once, including on the road to Kintamani, which drops everything.', false, '2026-08-25T03:00:00+00:00', '2026-08-25T03:00:00+00:00'),
  ('5b27facc-02e3-5936-a3f9-dc32f08afae0', 'Used it four times this year. Ten minutes by the roadside and I''m moving again, without pushing the bike to a workshop.', false, '2026-09-30T03:00:00+00:00', '2026-09-30T03:00:00+00:00'),
  ('ae0b3861-f8cf-587b-ad22-8a4cdd61cf79', 'Coffee from home is still hot at the top of the pass. It fits the hook under the handlebars, which is the only reason I chose this size.', false, '2026-09-16T03:00:00+00:00', '2026-09-16T03:00:00+00:00')
